ALTER TABLE "legacy_nxpkg_imports" DROP CONSTRAINT "legacy_nxpkg_imports_error_code_check";--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" DROP CONSTRAINT "legacy_nxpkg_imports_lifecycle_check";--> statement-breakpoint
DROP INDEX "legacy_nxpkg_imports_one_active_idx";--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" ADD COLUMN "adopt_report" jsonb;--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" ADD COLUMN "adopt_legacy_run_id" uuid;--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" ADD CONSTRAINT "legacy_nxpkg_imports_tenant_adopt_run_fk" FOREIGN KEY ("tenant_id","adopt_legacy_run_id") REFERENCES "public"."legacy_import_runs"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "legacy_nxpkg_imports_one_active_idx" ON "legacy_nxpkg_imports" USING btree ("tenant_id") WHERE NOT (status IN ('VERIFY_FAILED', 'DRY_RUN_FAILED', 'COMPLETED', 'COMPLETED_WITH_DISCREPANCY', 'FAILED', 'CANCELLED', 'ADOPT_DONE'));--> statement-breakpoint
ALTER TABLE "legacy_import_runs" ADD CONSTRAINT "legacy_import_runs_mode_check" CHECK (mode IN ('DRY_RUN', 'APPLY', 'ADOPT_APPROVED'));--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" ADD CONSTRAINT "legacy_nxpkg_imports_adopt_check" CHECK (((status = 'ADOPT_DONE') = (adopt_report IS NOT NULL)) AND (adopt_legacy_run_id IS NULL OR adopt_report IS NOT NULL) AND (status NOT IN ('ADOPT_REQUESTED', 'ADOPT_RUNNING', 'ADOPT_DONE') OR (approved_at IS NULL AND apply_legacy_run_id IS NULL AND pre_import_backup_run_id IS NULL)));--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" ADD CONSTRAINT "legacy_nxpkg_imports_status_check" CHECK (status IN ('UPLOADED', 'VERIFYING', 'VERIFIED', 'VERIFY_FAILED', 'DRY_RUN_REQUESTED', 'DRY_RUN_RUNNING', 'DRY_RUN_DONE', 'DRY_RUN_FAILED', 'APPROVED', 'APPLYING', 'COMPLETED', 'COMPLETED_WITH_DISCREPANCY', 'FAILED', 'CANCELLED', 'ADOPT_REQUESTED', 'ADOPT_RUNNING', 'ADOPT_DONE'));--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" ADD CONSTRAINT "legacy_nxpkg_imports_error_code_check" CHECK ((error_code IS NULL OR error_code IN ('NXPKG_CONTAINER_INVALID', 'NXPKG_WRONG_KEY', 'NXPKG_TAMPERED', 'NXPKG_UNSUPPORTED_VERSION', 'NXPKG_NOT_READY', 'NXPKG_SOURCE_SNAPSHOT_MISSING', 'NXPKG_MONEY_UNIT', 'NXPKG_LIVE_FLAG', 'PANEL_TARGET_MISMATCH', 'FRESH_TARGET_NOT_EMPTY', 'PACKAGE_CHANGED', 'DRY_RUN_MISMATCH', 'DECISIONS_INVALID', 'IMPORT_FAILED', 'PRE_IMPORT_BACKUP_FAILED', 'SUPERSEDED_BY_RESTORE', 'APPROVAL_EXPIRED', 'CANCELLED', 'ADOPT_REFUSED')) AND ((status IN ('VERIFY_FAILED', 'DRY_RUN_FAILED', 'FAILED', 'CANCELLED')) = (error_code IS NOT NULL)));--> statement-breakpoint
ALTER TABLE "legacy_nxpkg_imports" ADD CONSTRAINT "legacy_nxpkg_imports_lifecycle_check" CHECK ((finished_at IS NOT NULL) = (status IN ('VERIFY_FAILED', 'DRY_RUN_FAILED', 'COMPLETED', 'COMPLETED_WITH_DISCREPANCY', 'FAILED', 'CANCELLED', 'ADOPT_DONE')));